.cr_robust_margin<-function(prediction,target){
 if(is.null(prediction)||target$kind=='POLICY_ACTION')return(NULL)
 if(target$operator=='<=')return(target$value-prediction)
 if(target$operator=='>=')return(prediction-target$value)
 v<-unlist(target$value);min(prediction-v[1],v[2]-prediction)
}
assess_counterfactual_robustness<-function(candidates,record,model_variants,scenarios,feasibility_contract,target,candidate_ids,nominal_variant_id,context=NULL){
 if(!.cr_object(model_variants)||!nominal_variant_id%in%names(model_variants)) .cr_error('ROBUSTNESS_MODELS','Named local model variants including nominal required');.cr_pfs_ids(names(model_variants),'model_variant_ids');nominal<-model_variants[[nominal_variant_id]]
 if(!.cr_object(nominal)) .cr_error('ROBUSTNESS_MODELS','Each variant needs predictor and model_contract');.cr_data_required(nominal,c('predictor','model_contract'));checked<-.cr_ex_contract(nominal$model_contract,context);features<-checked$features;ctx<-checked$context;target<-.cr_cf_target(target);base<-.cr_numeric(record,'record',vector_only=TRUE);x<-.cr_pfs_matrix(candidates,'candidates');ids<-.cr_pfs_ids(candidate_ids,'candidate_ids')
 if(length(base)!=length(features)||!identical(dim(x),c(length(ids),length(features)))) .cr_error('ROBUSTNESS_SHAPE','Aligned candidate matrix and baseline required')
 .cr_local_constraints(feasibility_contract,features);contracts<-list()
 for(vid in names(model_variants)){v<-model_variants[[vid]];if(!.cr_object(v)) .cr_error('ROBUSTNESS_MODELS','Each variant needs predictor and model_contract');.cr_data_required(v,c('predictor','model_contract'));vf<-.cr_ex_contract(v$model_contract,context)$features
  if(!identical(vf,features)||!identical(.cr_hash(v$model_contract$target),.cr_hash(nominal$model_contract$target))||v$model_contract$output_scale!=nominal$model_contract$output_scale||!is.function(v$predictor)) .cr_error('ROBUSTNESS_MODELS','Variants must share feature order, output scale and target with callable predictions')
  if(target$kind=='POLICY_ACTION'&&(!is.function(v$policy_evaluator)||!.cr_object(v$policy_contract))) .cr_error('ROBUSTNESS_MODELS','Policy targets require full replay for every variant');contracts[[vid]]<-list(model_contract=v$model_contract,policy_contract=v$policy_contract)
 }
 rows<-.cr_data_rows(scenarios,'scenarios');.cr_pfs_ids(lapply(rows,function(r)r$scenario_id),'scenario_ids');weights<-.cr_pf_weights(unlist(lapply(rows,function(r)r$weight)),length(rows));deltas<-list()
 for(row in rows){.cr_data_required(row,c('scenario_id','model_variant_id','delta','weight'));if(!row$model_variant_id%in%names(model_variants)) .cr_error('ROBUSTNESS_MODELS','Unknown scenario model variant');delta<-.cr_numeric(unlist(row$delta),'delta',vector_only=TRUE);if(length(delta)!=length(base)) .cr_error('ROBUSTNESS_SHAPE','One additive measurement perturbation per feature required');deltas[[length(deltas)+1L]]<-delta}
 evaluate<-function(vid,delta){v<-model_variants[[vid]]
  tryCatch({ice<-compute_credit_ice(v$predictor,base+delta,sweep(x,2,delta,'+'),v$model_contract,feasibility_contract,varying_features=features,policy_evaluator=v$policy_evaluator,policy_contract=v$policy_contract,context=context)$value
   lapply(seq_along(ids),function(i){feasible<-length(ice$feasibility_findings[[i]])==0;list(candidate_id=ids[i],feasible=feasible,findings=ice$feasibility_findings[[i]],prediction=ice$predictions[[i]],policy_decision=ice$policy_decisions[[i]],target_satisfied=feasible&&.cr_cf_success(ice$predictions[[i]],ice$policy_decisions[[i]],target),target_margin=.cr_robust_margin(ice$predictions[[i]],target),error_code=NULL)})
  },error=function(error){if(!inherits(error,'creditratingsystem_error'))stop(error);lapply(ids,function(cid)list(candidate_id=cid,feasible=NULL,findings=list(),prediction=NULL,policy_decision=NULL,target_satisfied=FALSE,target_margin=NULL,error_code=error$code))})
 }
 nominal_results<-evaluate(nominal_variant_id,rep(0,length(features)));reports<-lapply(seq_along(rows),function(i)list(scenario_id=rows[[i]]$scenario_id,model_variant_id=rows[[i]]$model_variant_id,delta=as.list(deltas[[i]]),normalized_weight=weights[i],candidates=evaluate(rows[[i]]$model_variant_id,deltas[[i]])))
 summaries<-lapply(seq_along(ids),function(i){results<-lapply(reports,function(r)r$candidates[[i]]);success<-vapply(results,function(r)r$target_satisfied,logical(1));known<-vapply(results,function(r)is.null(r$error_code)&&identical(r$feasible,TRUE),logical(1));margins<-lapply(results,function(r)r$target_margin);all_margins<-all(lengths(margins)==1)
  list(candidate_id=ids[i],nominal=nominal_results[[i]],all_scenarios_succeed=all(success),scenario_success_fraction=sum(weights*success),scenario_feasibility_lower=sum(weights*vapply(results,function(r)identical(r$feasible,TRUE),logical(1))),scenario_feasibility_upper=sum(weights*vapply(results,function(r)!identical(r$feasible,FALSE),logical(1))),unevaluable_weight=sum(weights*vapply(results,function(r)!is.null(r$error_code),logical(1))),failed_scenario_ids=as.list(vapply(rows[!success],function(r)r$scenario_id,'')),worst_target_margin=if(all_margins)min(unlist(margins))else NULL,best_target_margin=if(all_margins)max(unlist(margins))else NULL,evaluated_prediction_count=sum(known))
 })
 failed<-vapply(reports,function(r)any(!vapply(r$candidates,function(c)c$target_satisfied,logical(1))),logical(1));fragile<-lapply(seq_along(features),function(j){vals<-vapply(deltas,function(d)d[j],0.);list(feature_id=features[j],minimum_delta=min(vals),maximum_delta=max(vals),varies_across_scenarios=min(vals)!=max(vals),failed_scenarios_with_nonzero_delta=as.list(vapply(reports[failed&vals!=0],function(r)r$scenario_id,'')))})
 .cr_result(list(target=target,nominal_variant_id=nominal_variant_id,candidate_ids=as.list(ids),candidate_summaries=summaries,scenarios=reports,feature_perturbation_report=fragile,scenario_count=length(rows),weight_interpretation='DECLARED_FINITE_SCENARIO_MASS_NOT_INTERVENTION_PROBABILITY'),'explainability.assess_counterfactual_robustness','robustness',ctx,diagnostics=list(variant_contracts_hash=.cr_hash(contracts),scenario_hash=.cr_hash(rows),feasibility_hash=.cr_hash(feasibility_contract)),limitations='Measurement perturbations are added to both baseline and candidates, so immutable features mean no action, not zero measurement uncertainty. Every supplied scenario remains in denominators, including failed evaluations. Reported feasibility bounds assign unknown feasibility to neither/both endpoints. Success fractions are finite scenario summaries, not real intervention probabilities or continuous worst-case guarantees. Feature/failure co-occurrence is descriptive, not causal attribution.')
}
